package app.loveu;

import android.app.AlertDialog;
import android.app.DatePickerDialog;
import android.view.View;
import android.widget.*;
import org.json.*;
import java.time.*;
import java.time.temporal.ChronoUnit;
import java.util.*;

/** Optional WorkBuddy pages. The legacy PeriodView is intentionally independent. */
final class WorkbuddyPeriodView extends LinearLayout {
    final MainActivity a;
    final boolean partner;
    final String key;
    String page="overview",returnPage="overview";
    JSONObject editing;
    WorkbuddyPeriodView(MainActivity activity){super(activity);a=activity;setOrientation(VERTICAL);partner="男".equals(a.settings().optString("profileGender"));key=partner?"menstrualPartner":"menstrualSelf";render();}
    boolean back(){if(page.equals("overview"))return false;page="overview";editing=null;render();return true;}
    void open(String value){page=value;render();}
    JSONArray data(){JSONArray values=a.root.optJSONArray(key);return values==null?new JSONArray():values;}
    List<JSONObject> sorted(){List<JSONObject> values=new ArrayList<>();JSONArray all=data();for(int i=0;i<all.length();i++)if(all.optJSONObject(i)!=null)values.add(all.optJSONObject(i));values.sort((x,y)->y.optString("start").compareTo(x.optString("start")));return values;}
    List<PeriodAnalysis.Entry> entries(JSONArray values,String skip)throws Exception{List<PeriodAnalysis.Entry> out=new ArrayList<>();for(int i=0;i<values.length();i++){JSONObject e=values.getJSONObject(i);if(!e.optString("id").equals(skip))out.add(new PeriodAnalysis.Entry(e.getString("start"),e.isNull("end")?null:e.getString("end")));}return out;}
    JSONObject active(){for(JSONObject value:sorted())if(value.isNull("end"))return value;return null;}
    void render(){removeAllViews();if(!page.equals("overview"))addView(a.button("‹ 返回经期首页",()->back()));a.attempt(()->{switch(page){case "ongoing":ongoing();break;case "history":history();break;case "analysis":analysis();break;case "reminder":reminders();break;case "edit":form();break;default:overview();}});}
    void title(String value){TextView text=a.text(value,24,a.ink);text.setTypeface(null,android.graphics.Typeface.BOLD);text.setPadding(0,a.dp(8),0,a.dp(16));addView(text);}
    LinearLayout card(){LinearLayout card=Ui.card(a);card.setBackground(Ui.stroke(Ui.SURFACE,Ui.BORDER,24,a));addView(card);return card;}
    void actionRow(LinearLayout parent,String[] labels,Runnable[] tasks){for(int offset=0;offset<labels.length;offset+=2){LinearLayout row=new LinearLayout(a);parent.addView(row);for(int i=offset;i<Math.min(offset+2,labels.length);i++){Button button=a.button(labels[i],tasks[i]);button.setTextSize(14);button.setMinHeight(a.dp(48));button.setSingleLine(!Language.latin());if(Language.latin())button.setMaxLines(2);button.setContentDescription(Language.ui(labels[i]));if(labels[i].equals("今天开始")){button.setBackground(Ui.stroke(Ui.PINK,Ui.PINK,18,a));button.setTextColor(a.berry);}if(labels[i].equals("今天结束")){button.setBackground(Ui.stroke(a.berry,a.berry,18,a));button.setTextColor(Ui.ON_ACCENT);}LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,a.dp(52),1);lp.setMargins(i==offset?0:a.dp(4),a.dp(8),i==Math.min(offset+2,labels.length)-1?0:a.dp(4),0);row.addView(button,lp);}}}
    String date(String value){try{LocalDate day=LocalDate.parse(value);return day.getYear()+"年"+day.getMonthValue()+"月"+day.getDayOfMonth()+"日";}catch(Exception ignored){return value;}}
    String label(JSONObject item){return date(item.optString("start"))+" – "+(item.isNull("end")?"进行中":date(item.optString("end")));}
    void overview()throws Exception{
        title(partner?"关怀大姨妈":"记录大姨妈");JSONObject current=active();LinearLayout state=card();
        if(current!=null){long days=ChronoUnit.DAYS.between(LocalDate.parse(current.getString("start")),LocalDate.now())+1;state.addView(a.text("进行中 · 第 "+days+" 天",21,a.ink));state.addView(a.text("开始于 "+date(current.getString("start")),14,a.muted));state.setContentDescription(Language.ui("经期进行中，第 "+days+" 天，查看详情"));state.setOnClickListener(v->open("ongoing"));state.addView(a.button("查看进行中经期 ›",()->open("ongoing")));}
        else{state.addView(a.text(sorted().isEmpty()?"从这一次开始记录":"当前没有进行中的经期",18,a.ink));state.addView(a.text(partner?"主动帮她记住每一个周期":"照顾自己的每一个周期",14,a.muted));}
        addView(PeriodForecastCard.create(a,partner));
        actionRow(this,new String[]{current==null?"今天开始":"进行中","补记","分析","历史"},new Runnable[]{current==null?()->saveStart():()->open("ongoing"),()->edit(null),()->open("analysis"),()->open("history")});
        if(!sorted().isEmpty()){JSONObject latest=sorted().get(0);TextView last=a.text("最近开始于 "+date(latest.getString("start")),13,a.muted);last.setPadding(0,a.dp(16),0,a.dp(8));addView(last);}else addView(a.text("暂无经期记录；补记后可查看历史和分析",13,a.muted));
        addView(a.button("分享所有经期记录给爱人",()->BulkShareDialog.show(a,"period")));
        addView(a.button("关怀提醒 ›",()->open("reminder")));
    }
    void ongoing()throws Exception{
        title("经期进行中");JSONObject current=active();if(current==null){addView(a.text("当前没有进行中的经期",15,a.muted));return;}
        LinearLayout state=card();long days=ChronoUnit.DAYS.between(LocalDate.parse(current.getString("start")),LocalDate.now())+1;state.addView(a.text("第 "+days+" 天",36,a.berry));state.addView(a.text("开始于 "+date(current.getString("start")),15,a.muted));
        actionRow(state,new String[]{"今天结束","编辑"},new Runnable[]{()->a.attempt(()->{JSONObject update=new JSONObject().put("id",current.getString("id")).put("end",LocalDate.now().toString());save(update,true);open("overview");}),()->edit(current)});
    }
    void history()throws Exception{
        title("经期历史");List<JSONObject> records=sorted();addView(a.text("全部本机历史 · "+records.size()+" 段",13,Ui.MUTED));if(records.isEmpty()){LinearLayout empty=card();empty.addView(a.text("还没有经期记录",18,a.ink));empty.addView(a.text("今天开始或补记过去的经期",14,a.muted));empty.addView(a.button("补记经期",()->edit(null)));return;}
        for(JSONObject item:records){LinearLayout box=card();box.addView(a.text(label(item),18,a.ink));box.addView(a.text("经量 "+unknown(item.optString("flow"))+" · 疼痛 "+unknown(item.optString("pain")),14,a.muted));if(!item.optString("symptoms").isEmpty())box.addView(a.text(Language.raw(item.optString("symptoms")),14,a.muted));actionRow(box,new String[]{"编辑","删除"},new Runnable[]{()->edit(item),()->confirmDelete(item)});box.addView(a.button("分享这段经期给伴侣",()->WorkbuddyCoupleView.preview(a,item,"period",partner)));}
    }
    String unknown(String value){return value.isEmpty()?"未填写":value;}
    void confirmDelete(JSONObject item){a.confirm("删除 "+label(item)+" 的经期？删除后不可恢复。",()->a.attempt(()->{delete(item.getString("id"));render();}));}
    void analysis()throws Exception{
        title("经期分析");addView(PeriodForecastCard.create(a,partner));LinearLayout summary=card();summary.addView(a.text("周期摘要",18,a.ink));summary.addView(a.text(PeriodAnalysis.summary(PeriodRecords.entries(a.root,partner),LocalDate.now()),14,a.muted));
        PeriodForecast.Result forecast=PeriodForecast.analyze(PeriodRecords.entries(a.root,partner),LocalDate.now());TreeMap<String,Integer> lengths=forecast.lengths;
        LinearLayout trend=card();trend.addView(a.text("经期天数趋势",18,a.ink));if(lengths.isEmpty())trend.addView(a.text("结束一段经期后显示实际天数",14,a.muted));else{HorizontalScrollView scroll=new HorizontalScrollView(a);scroll.setHorizontalScrollBarEnabled(false);scroll.addView(new WorkbuddyPeriodBars(a,lengths),new android.view.ViewGroup.LayoutParams(Math.max(a.dp(280),a.dp(lengths.size()*64)),a.dp(190)));trend.addView(scroll);}
        LinearLayout cycles=card();cycles.addView(a.text("周期长度趋势",18,a.ink));if(forecast.cycles.isEmpty())cycles.addView(a.text("至少两段记录后显示周期间隔",14,a.muted));else{HorizontalScrollView sc=new HorizontalScrollView(a);sc.setHorizontalScrollBarEnabled(false);WorkbuddyPeriodBars cycleBars=new WorkbuddyPeriodBars(a,forecast.cycles);cycleBars.setContentDescription(Language.ui("相邻经期开始日期间隔趋势，单位天"));sc.addView(cycleBars,new android.view.ViewGroup.LayoutParams(Math.max(a.dp(280),a.dp(forecast.cycles.size()*64)),a.dp(190)));cycles.addView(sc);}
        addView(a.text("预计范围不用于避孕判断",12,a.muted));addView(a.button("ⓘ 分析口径",()->{AlertDialog dialog=new LanguageDialog(a).setTitle("经期分析口径").setMessage("经期天数含开始与结束日；进行中记录不计入平均经期天数。周期中位数依据最近最多6个相邻开始日期间隔；至少三段记录才显示估计范围。全部历史长期保留，不按预测窗口删除。样本较少，仅供参考。").setPositiveButton("我知道了",null).create();a.dialogs.add(dialog);dialog.show();WorkbuddyUi.decorate(dialog);}));
    }
    void reminders(){
        title("关怀提醒");long time=a.settings().optLong(key+"Reminder",0);boolean future=time>System.currentTimeMillis();LinearLayout box=card();box.addView(a.text("提醒日期",18,a.ink));box.addView(a.text(future?date(Instant.ofEpochMilli(time).atZone(ZoneId.systemDefault()).toLocalDate().toString())+" 上午 9:00":time>0?"所设日期已过去":"尚未设置提醒",18,a.ink));box.setContentDescription(Language.ui("提醒日期，点击选择"));box.setOnClickListener(v->reminder());box.addView(a.button(future?"修改提醒日期":"选择提醒日期",()->reminder()));
        addView(a.text("固定所选日期上午 9 点，仅未来日期可设",13,a.muted));boolean allowed=notificationAllowed();addView(a.text(allowed?"通知已授权": "通知未授权，无法收到提醒",13,a.muted));if(!allowed)addView(a.button("允许通知",()->requestNotifications()));
        if(time>0)addView(a.button("取消提醒",()->a.attempt(()->{writeReminder(0);render();})));
    }
    boolean notificationAllowed(){if(android.os.Build.VERSION.SDK_INT>=33&&a.checkSelfPermission("android.permission.POST_NOTIFICATIONS")!=android.content.pm.PackageManager.PERMISSION_GRANTED)return false;return android.os.Build.VERSION.SDK_INT<24||((android.app.NotificationManager)a.getSystemService(android.content.Context.NOTIFICATION_SERVICE)).areNotificationsEnabled();}
    void requestNotifications(){if(android.os.Build.VERSION.SDK_INT>=33&&a.checkSelfPermission("android.permission.POST_NOTIFICATIONS")!=android.content.pm.PackageManager.PERMISSION_GRANTED)a.requestPermissions(new String[]{"android.permission.POST_NOTIFICATIONS"},73);else{android.content.Intent intent=new android.content.Intent(android.provider.Settings.ACTION_APP_NOTIFICATION_SETTINGS);intent.putExtra(android.provider.Settings.EXTRA_APP_PACKAGE,a.getPackageName());a.startActivity(intent);}}
    void reminder(){if(!notificationAllowed()){requestNotifications();Toast.makeText(a,Language.ui("允许通知后，再选择提醒日期"),Toast.LENGTH_SHORT).show();return;}LocalDate now=LocalDate.now();long existing=a.settings().optLong(key+"Reminder",0);LocalDate selected=existing>System.currentTimeMillis()?Instant.ofEpochMilli(existing).atZone(ZoneId.systemDefault()).toLocalDate():now.plusDays(1);DatePickerDialog dialog=new DatePickerDialog(a,(view,y,m,d)->a.attempt(()->{long time=LocalDate.of(y,m+1,d).atTime(9,0).atZone(ZoneId.systemDefault()).toInstant().toEpochMilli();if(time<=System.currentTimeMillis())throw new IllegalArgumentException("请选择未来日期，提醒时间为上午9点");writeReminder(time);render();}),selected.getYear(),selected.getMonthValue()-1,selected.getDayOfMonth());dialog.getDatePicker().setMinDate(System.currentTimeMillis());a.dialogs.add(dialog);dialog.show();}
    void writeReminder(long time)throws Exception{if(a.locked)throw new IllegalStateException("请先解锁");JSONObject latest=a.vault.read();JSONObject settings=latest.optJSONObject("settings");if(settings==null){settings=new JSONObject();latest.put("settings",settings);}if(time==0)settings.remove(key+"Reminder");else settings.put(key+"Reminder",time);a.vault.write(latest);a.root=latest;PeriodReminder.schedule(a,key,time);}
    void edit(JSONObject original){editing=original;returnPage=page;page="edit";render();}
    void pick(EditText target,boolean canClear){LocalDate selected;try{selected=LocalDate.parse(target.getText().toString());}catch(Exception ignored){selected=LocalDate.now();}DatePickerDialog dialog=new DatePickerDialog(a,(view,y,m,d)->target.setText(LocalDate.of(y,m+1,d).toString()),selected.getYear(),selected.getMonthValue()-1,selected.getDayOfMonth());dialog.getDatePicker().setMaxDate(System.currentTimeMillis());if(canClear)dialog.setButton(android.content.DialogInterface.BUTTON_NEUTRAL,Language.ui("设为进行中"),(d,w)->target.setText(""));a.dialogs.add(dialog);dialog.show();}
    void chips(LinearLayout box,String title,String[] options,String[] selected){box.addView(a.text(title,17,a.ink));List<Button> buttons=new ArrayList<>();LinearLayout row=null;for(int i=0;i<options.length;i++){if(i%3==0){row=new LinearLayout(a);box.addView(row);}String value=options[i];Button button=a.button(value,()->{});button.setTextSize(14);buttons.add(button);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,a.dp(44),1);lp.setMargins(a.dp(3),a.dp(5),a.dp(3),a.dp(5));row.addView(button,lp);styleChip(button,value.equals(selected[0]));button.setOnClickListener(v->{selected[0]=value;for(Button other:buttons)styleChip(other,Language.source(other).equals(value));});}if(selected[0]!=null&&!Arrays.asList(options).contains(selected[0]))box.addView(a.text("原记录："+selected[0]+"（选择后更新）",13,a.muted));}
    void styleChip(Button button,boolean selected){button.setBackground(Ui.stroke(selected?Ui.PINK:Ui.SURFACE,selected?Ui.PINK:Ui.BORDER,16,a));button.setTextColor(selected?a.berry:a.muted);button.setSelected(selected);button.setContentDescription(Language.ui(Language.source(button)+(selected?" 已选择":" 未选择")));}
    void form()throws Exception{
        title(editing==null?"记录经期":"编辑经期");JSONObject original=editing;LinearLayout dateCard=card();EditText start=a.field(dateCard,"开始日期",original==null?LocalDate.now().toString():original.optString("start"),1);start.setFocusable(false);start.setContentDescription(Language.ui("开始日期，点击选择"));start.setOnClickListener(v->pick(start,false));
        boolean completed=original!=null&&!original.isNull("end");LinearLayout status=card();status.addView(a.text("状态",15,a.muted));final boolean[] ended={completed};LinearLayout endBox=a.column();EditText end=a.field(endBox,"结束日期",completed?original.optString("end"):LocalDate.now().toString(),1);end.setFocusable(false);end.setContentDescription(Language.ui("结束日期，点击选择"));end.setOnClickListener(v->pick(end,false));List<Button> statusButtons=new ArrayList<>();LinearLayout stateRow=new LinearLayout(a);status.addView(stateRow);for(String value:new String[]{"进行中","已结束"}){Button button=a.button(value,()->{});statusButtons.add(button);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,a.dp(44),1);lp.setMargins(a.dp(3),a.dp(8),a.dp(3),a.dp(8));stateRow.addView(button,lp);styleChip(button,completed==value.equals("已结束"));button.setOnClickListener(v->{ended[0]=value.equals("已结束");endBox.setVisibility(ended[0]?View.VISIBLE:View.GONE);for(Button other:statusButtons)styleChip(other,ended[0]==Language.source(other).equals("已结束"));});}status.addView(endBox);endBox.setVisibility(completed?View.VISIBLE:View.GONE);
        String[] flow={original==null?"未填写":original.optString("flow","未填写")},pain={original==null?"未填写":original.optString("pain","未填写")};chips(this,"经量",new String[]{"未填写","少","中","多"},flow);chips(this,"疼痛",new String[]{"未填写","无","轻度","中度","重度"},pain);
        LinearLayout notes=card();EditText symptoms=a.field(notes,"症状 / 关怀备注（可不填）",original==null?"":original.optString("symptoms"),131073);symptoms.setMinLines(3);addView(a.button("取消",()->{page=returnPage;editing=null;render();}));addView(a.button("保存",()->a.attempt(()->{JSONObject value=original==null?new JSONObject().put("id",UUID.randomUUID().toString()):new JSONObject(original.toString());value.put("start",start.getText().toString().trim()).put("end",ended[0]?end.getText().toString().trim():JSONObject.NULL).put("flow",flow[0]).put("pain",pain[0]).put("symptoms",symptoms.getText().toString().trim());save(value,original!=null);page=returnPage;editing=null;render();})));
    }
    void saveStart(){a.attempt(()->{save(new JSONObject().put("id",UUID.randomUUID().toString()).put("start",LocalDate.now().toString()).put("end",JSONObject.NULL),false);open("ongoing");});}
    void save(JSONObject value)throws Exception{save(value,false);}
    void save(JSONObject value,boolean requireExisting)throws Exception{
        if(a.locked)throw new IllegalStateException("请先解锁");JSONObject latest=a.vault.read();JSONArray all=latest.optJSONArray(key);if(all==null)all=new JSONArray();JSONObject existing=null;for(int i=0;i<all.length();i++)if(all.getJSONObject(i).optString("id").equals(value.getString("id")))existing=all.getJSONObject(i);if(requireExisting&&existing==null)throw new IllegalStateException("这段经期已删除，请返回查看最新记录");
        JSONObject merged=existing==null?new JSONObject(value.toString()):new JSONObject(existing.toString());for(String field:new String[]{"start","end","flow","pain","symptoms"})if(value.has(field))merged.put(field,value.get(field));PeriodAnalysis.validate(new PeriodAnalysis.Entry(merged.getString("start"),merged.isNull("end")?null:merged.getString("end")),entries(all,value.getString("id")),LocalDate.now());JSONArray next=new JSONArray();boolean replaced=false;for(int i=0;i<all.length();i++){JSONObject item=all.getJSONObject(i);if(item.getString("id").equals(value.getString("id"))){next.put(merged);replaced=true;}else next.put(item);}if(!replaced)next.put(merged);latest.put(key,next);a.vault.write(latest);a.root=latest;
    }
    void delete(String id)throws Exception{if(a.locked)throw new IllegalStateException("请先解锁");JSONObject latest=a.vault.read();JSONArray all=latest.optJSONArray(key),keep=new JSONArray();if(all!=null)for(int i=0;i<all.length();i++){JSONObject item=all.getJSONObject(i);if(!id.equals(item.getString("id")))keep.put(item);}latest.put(key,keep);a.vault.write(latest);a.root=latest;}
}
